window.AUTH=window.AUTH||{};window.AUTH["21-908"]={"d":"21-908","id":"2022/21-908","n":"Bartenwerfer v. Buckley","briefs":[{"k":"petitioner","label":"Brief of petitioner Kate Bartenwerfer","date":"2022-07-19","url":"https://www.supremecourt.gov/DocketPDF/21/21-908/230392/20220719144833977_Bartenwerfer%20Opening%20Brief.pdf","side":"pet","n":49},{"k":"respondent","label":"Brief of respondent Kieran Buckley","date":"2022-09-22","url":"https://www.supremecourt.gov/DocketPDF/21/21-908/238543/20220922123540131_21-908%20Buckley%20Br..pdf","side":"res","n":91},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2022-09-29","url":"https://www.supremecourt.gov/DocketPDF/21/21-908/242080/20220929135654610_21-908bsacUnitedStates.pdf","side":"us","n":69},{"k":"reply","label":"Reply of petitioner Kate Bartenwerfer","date":"2022-10-24","url":"https://www.supremecourt.gov/DocketPDF/21/21-908/243749/20221024131709229_Bartenwerfer%20Reply%20Brief.pdf","side":"pet","n":40}],"opinion":"https://www.supremecourt.gov/opinions/22pdf/598us1r5_1b72.pdf","tr":true,"items":[{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"op":1,"sum":"The Court held that there is no private right of action to enforce disparate-impact regulations promulgated under Title VI. \"Title VI itself directly reaches only instances of intentional discrimination,\" wrote Justice Scalia, \"[n]either as originally enacted nor as later amended does Title VI display an intent to create a freestanding private right of action to enforce regulations promulgated under [section 602].\" Justice John Paul Stevens filed a dissenting opinion, which was join by Justices David H. Souter, Ruth Bader Ginsburg, and Stephen G. Breyer.","sumSrc":"Oyez","by":{"0":"43"}},{"t":"case","label":"Atherton v. FDIC","cite":"519 U.S. 213","y":1997,"id":"1996/95-928","sc":1,"sum":"The unanimous Court concluded that \"state law sets the standard of conduct as long as the state standard is stricter than that of the federal statute.\" The opinion by Justice Stephen Breyer held that the federal \"gross negligence\" statute was only intended to set a \"floor\" or minimum standard for state laws governing negligent conduct.","sumSrc":"Oyez","by":{"0":"43","3":"22"}},{"t":"case","label":"Bank of Am. Nat’l Tr. & Sav. Ass’n v. 203 N. LaSalle St. P’ship","cite":"526 U.S. 434","y":1999,"id":"1998/97-1418","sc":1,"sum":"A debtor's prebankruptcy equity holders may not contribute new capital and receive ownership in the debtor's reorganization entity","sumSrc":"Oyez","by":{"0":"44"}},{"t":"case","label":"Bostock v. Clayton County","cite":"140 S. Ct. 1731","y":2020,"id":"2019/17-1618","sc":1,"sum":"The Court held that Title VII of the Civil Rights Act of 1964, which prohibits against employment discrimination “because of . . . sex” encompasses discrimination based on an individual’s sexual orientation.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Briggs v. Spaulding","cite":"141 U.S. 132","y":1891,"id":"scdb/1890-297","sc":1,"sum":"The degree of care required of directors of corporations depends upon the Subject to which it is to be applied, and each case is to be determined in view of all the circumstances.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"41, 43"}},{"t":"case","label":"Bullock v. BankChampaign, N.A.","cite":"569 U.S. 267","y":2013,"id":"2012/11-1518","sc":1,"op":2,"ar":4,"sum":"The Court held that debts arising out of fraud or defalcation in a fiduciary capacity are not dischargeable in bankruptcy proceedings.","sumSrc":"Oyez","by":{"0":"13, 17, 29, 47","1":"32","2":"14","3":"3, 12, 18"}},{"t":"case","label":"Cent. Bank of Denver, N.A. v. First Interstate Bank of Denver, N.A.","cite":"511 U.S. 164","y":1994,"id":"1993/92-854","sc":1,"sum":"The Court held that the Securities Exchange Act only prohibits manipulative or deceitful actions, and it can only be used to prosecute such actions. Since the charge of aiding and abetting is not directly covered in the statute, companies cannot be liable for such actions.","sumSrc":"Oyez","by":{"0":"43","3":"20"}},{"t":"case","label":"Cent. Va. Cmty. Coll. v. Katz","cite":"546 U.S. 356","y":2006,"id":"2005/04-885","sc":1,"sum":"The Court ruled that states cannot invoke sovereign immunity as a defense in bankruptcy proceedings. Rather than ruling on the power of Congress under the Bankruptcy Clause to waive states' immunity, as the bankruptcy court did, the Court held that ratification of the Clause itself involved a subordination of state sovereign immunity.","sumSrc":"Oyez","by":{"0":"16"}},{"t":"case","label":"Cohen v. de la Cruz","cite":"523 U.S. 213","y":1998,"id":"1997/96-1923","sc":1,"op":1,"ar":6,"sum":"The Court ruled that because Section 523(a)(2)(A) of the Bankruptcy Code excepts from discharge all liability arising from fraud, treble damages (plus attorney's fees and costs) awarded on account of the debtor's fraud fall within the scope of the exception.","sumSrc":"Oyez","by":{"0":"18, 20, 28","1":"passim","2":"passim","3":"passim"}},{"t":"case","label":"Crawford v. Burke","cite":"195 U.S. 176","y":1904,"id":"scdb/1904-044","sc":1,"sum":"A plea puis darrien continuance waives all prior pleas and amounts to an admission of the plaintiff’s cause of action.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"37, 45"}},{"t":"case","label":"Doyle v. First Nat’l Bank of Balt.","cite":"231 F. 649","y":1916,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F./231/649/","by":{"0":"42"}},{"t":"case","label":"E.I. du Pont de Nemours & Co. v. Train","cite":"430 U.S. 112","y":1977,"id":"1976/75-978","sc":1,"op":1,"sum":"The Court held that the Environmental Protection Agency could place categorical pollution limits on existing manufacturing plants while also placing absolute pollution limits on newly constructed manufacturing plants.","sumSrc":"Oyez","by":{"0":"20, 31","2":"25"}},{"t":"case","label":"Erie R.R. Co. v. Tompkins","cite":"304 U.S. 64","y":1938,"id":"1900-1940/304us64","sc":1,"ar":1,"sum":"A case in which the Court overturned its prior decision in Swift v. Tyson and held that federal courts exercising diversity jurisdiction cannot create their own common law for issues that properly fall within state law.","sumSrc":"Oyez","by":{"0":"passim","2":"21","3":"2, 22, 24, 25"}},{"t":"case","label":"Field v. Mans","cite":"516 U.S. 59","y":1995,"id":"1995/94-967","sc":1,"op":4,"ar":13,"sum":"Interpreting § 523(a)(2)(A) with reference to the common law of fraud.","sumSrc":"opinion","by":{"0":"32","1":"23, 39","2":"14, 18, 21, 27","3":"7, 11, 18, 23"}},{"t":"case","label":"Frank v. Mich. Paper Co.","cite":"179 F. 776","y":1910,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F./179/776/","by":{"0":"42"}},{"t":"case","label":"Gilpin v. Merchants’ Bank","cite":"165 F. 607","y":1908,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F./165/607/","by":{"0":"42"}},{"t":"case","label":"Gladstone, Realtors v. Village of Bellwood","cite":"441 U.S. 91","y":1979,"id":"1978/77-1493","sc":1,"sum":"Section 812 of the Fair Housing Act of 1968 (Act) provides that the rights granted by § 804 against racial discrimination in the sales or rental of housing \"may be enforced by civil actions in appropriate United States district courts.\" Respondents (the village of Bellwood, one Negro and four white residents of Bellwood, and one Negro resident of a neighboring municipality) brought separate actions in District Court …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33","3":"8"}},{"t":"case","label":"Grogan v. Garner","cite":"498 U.S. 279","y":1991,"id":"1990/89-1149","sc":1,"op":1,"ar":1,"sum":"Courts should apply the \"preponderance of the evidence\" standard. Justice John Paul Stevens, for a unanimous Supreme Court, wrote that the lack of a specified standard of evidence in section 523(a) implied that Congress had intended the preponderance of the evidence standard to be used.","sumSrc":"Oyez","by":{"0":"24","1":"26","2":"3, 30","3":"10, 11, 12, 18"}},{"t":"case","label":"Hardie v. Swafford Bros. Dry Goods Co.","cite":"165 F. 588","y":1908,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F./165/588/","by":{"0":"42"}},{"t":"case","label":"Hartford Underwriters Ins. v. Union Planters Bank, N.A.","cite":"530 U.S. 1","y":2000,"id":"1999/99-409","sc":1,"ar":1,"sum":"The Court held that \"Section 506(c) does not provide an administrative claimant of a bankruptcy estate an independent right to seek payment of its claim from property encumbered by a secured creditor's lien, or subject to secured claims.","sumSrc":"Oyez","by":{"0":"32, 44","2":"30","3":"9"}},{"t":"case","label":"Husky Int’l Elecs., Inc. v. Ritz","cite":"578 U.S. 356","y":2016,"id":"2015/15-145","sc":1,"op":1,"ar":4,"sum":"The Court determined that the “actual fraud” language of the bankruptcy statute encompasses traditional forms of fraud and is not limited to fraudulent representation.","sumSrc":"Oyez","by":{"0":"22, 28, 35, 36","1":"15","2":"2, 9, 13, 16","3":"5, 7"}},{"t":"case","label":"Jama v. ICE","cite":"543 U.S. 335","y":2005,"id":"2004/03-674","sc":1,"sum":"Federal immigration law permitted an alien to be removed to a country without the advance consent of that country's government. Of the four removal options federal immigration law listed, an acceptance requirement appeared in only one clause: \"...he shall be removed to another country whose government will accept him.\" That clause only applied after the attorney general attempted the prior deportation option.","sumSrc":"Oyez","by":{"0":"44","3":"23, 24"}},{"t":"case","label":"James-Dickinson Farm Mortg. Co. v. Harry","cite":"273 U.S. 119","y":1927,"id":"scdb/1926-143","sc":1,"sum":"1. Jurisdiction over a corporation of one State cannot be acquired in another State in which it has no place of business and is not found, merely by serving process upon an executive officer temporarily therein, even if he be there on business of the company.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"42","3":"22, 24"}},{"t":"case","label":"Kawaauhau v. Geiger","cite":"523 U.S. 57","y":1998,"id":"1997/97-115","sc":1,"op":2,"sum":"The Court held that \"debts arising from recklessly or negligently inflicted injuries do not fall within the compass of [section 523(a)(6)].\" Therefore, the debt is dischargeable.","sumSrc":"Oyez","by":{"0":"17","1":"32","3":"3, 18"}},{"t":"case","label":"Lamar, Archer & Cofrin, LLP v. Appling","cite":"138 S. Ct. 1752","y":2018,"id":"2017/16-1215","sc":1,"op":1,"sum":"The Court decided that a statement regarding a specific asset can be a “statement respecting the debtor’s . . . financial condition” under section 523(a)(2)(B) of the Bankruptcy Code.","sumSrc":"Oyez","by":{"0":"passim","1":"20","2":"10, 18, 20, 27","3":"12"}},{"t":"case","label":"Lamie v. U.S. Tr.","cite":"540 U.S. 526","y":2004,"id":"2003/02-693","sc":1,"sum":"According to Justice Anthony Kennedy's opinion for the Court: \"The statute is awkward, and even ungrammatical; but that does not make it ambiguous on the point at issue.\" The Court ruled that though the Act's deletion of the words \"or to the debtor's attorney\" from the Bankruptcy Code had rendered a sentence grammatically incorrect, the Act should still be interpreted according to the plain meaning of its text, however awkward.","sumSrc":"Oyez","by":{"0":"43"}},{"t":"case","label":"Marrama v. Citizens Bank of Mass.","cite":"549 U.S. 365","y":2007,"id":"2006/05-996","sc":1,"op":1,"sum":"The Court ruled that there is a \"bad faith\" exception to the right of conversion in Section 706(a). The opinion by Justice John Paul Stevens held that although the vast majority of Chapter 7 debtors can convert to Chapter 13, a Chapter 7 debtor who engages in bad faith conduct does not qualify as a \"debtor\" under Chapter 13 and thus cannot convert his petition.","sumSrc":"Oyez","by":{"0":"16, 43"}},{"t":"case","label":"Marx v. Gen. Revenue Corp.","cite":"568 U.S. 371","y":2013,"id":"2012/11-1175","sc":1,"sum":"The Court held that the Federal Rules of Civil Procedure awards costs to the prevailing party unless a statute explicitly states otherwise.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"Mission Prod. Holdings, Inc. v. Tempnology, LLC","cite":"139 S. Ct. 1652","y":2019,"id":"2018/17-1657","sc":1,"sum":"A bankruptcy debtor’s rejection of an executory contract under 11 U. S. C. §365 has the same effect as a breach of that contract outside bankruptcy; such an act thus cannot rescind rights that the contract previously granted.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"4, 33","1":"23, 32","2":"10"}},{"t":"case","label":"Mohamad v. Palestinian Auth.","cite":"566 U.S. 449","y":2012,"id":"2011/11-88","sc":1,"sum":"The Court held that the word \"individual\" in the Torture Victim Protection Act means a natural person and does not impose any liability against organizations.","sumSrc":"Oyez","by":{"0":"18","1":"34"}},{"t":"case","label":"Neal v. Clark","cite":"95 U.S. 704","y":1878,"id":"scdb/1877-139","sc":1,"ar":3,"sum":"The facts out of which this case arises, so far as it is material to state them, are substantially these: —","sumSrc":"Headnote (U.S. Reports)","by":{"0":"16","1":"15, 18, 22, 39","2":"19"}},{"t":"case","label":"Ragan, Malone & Co. v. Cotton","cite":"200 F. 546","y":1912,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F./200/546/","by":{"0":"42"}},{"t":"case","label":"Rodriguez v. FDIC","cite":"140 S. Ct. 713","y":2020,"id":"2019/18-1269","sc":1,"sum":"A case in which the Court vacated the ruling below that had applied a federal common-law rule on how to allocate a tax refund paid to an affiliated group.","sumSrc":"Oyez","by":{"0":"43"}},{"t":"case","label":"Sachan v. Huh","cite":"506 B.R. 257","y":2014,"court":"B.A.P. 9th Cir.","url":"https://www.courtlistener.com/c/B.R./506/257/","by":{"0":"11","1":"8","3":"15"}},{"t":"case","label":"Schwab v. Reilly","cite":"560 U.S. 770","y":2010,"id":"2009/08-538","sc":1,"sum":"The Court held that someone who files for bankruptcy is allowed to retain the value of certain property that would otherwise be sold to pay off debts, up to a certain dollar limit; if the value of the property is more than the individual in bankruptcy estimated, the value above the pre-determined limit may be used to pay creditors.","sumSrc":"Oyez","by":{"0":"17","2":"14"}},{"t":"case","label":"Strang v. Bradner","cite":"114 U.S. 555","y":1885,"id":"scdb/1884-236","sc":1,"op":10,"ar":22,"sum":"The rule re-affirmed that the term “fraud,” in the clause defining the debts from which a bankrupt is not relieved by a discharge under the bankrupt act, means positive fraud or fraud in fact, involving moral turpitude or intentional wrong, not implied fraud, which may exist without bad faith.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"passim","1":"passim","2":"6, 8, 18, 19, 20","3":"passim"}},{"t":"case","label":"Tex. Indus., Inc. v. Radcliff Materials, Inc.","cite":"451 U.S. 630","y":1981,"id":"1980/79-1144","sc":1,"sum":"There is no basis in federal statutory or common law for allowing federal courts to fashion the right to contribution urged by petitioner.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43","3":"20"}},{"t":"case","label":"Unicolors, Inc. v. H&M Hennes & Maurtiz, L.P.","cite":"142 S. Ct. 941","y":2022,"id":"2021/20-915","sc":1,"sum":"Lack of either factual or legal knowledge can excuse an inaccuracy in a copyright registration under 17 U. S. C. §411(b)(1)(A)’s safe harbor.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"22","1":"31","3":"15"}},{"t":"case","label":"United States v. Briggs","cite":"141 S. Ct. 467","y":2020,"id":"2020/19-108","sc":1,"sum":"Respondents’ prosecutions for military rape were timely commenced under the Uniform Code of Military Justice’s statute of limitations.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"24, 43"}},{"t":"case","label":"United States v. Ron Pair Enters.","cite":"489 U.S. 235","y":1989,"id":"1988/87-1043","sc":1,"sum":"Section 506(b) entitles a creditor to receive postpetition interest on a nonconsensual oversecured claim allowed in a bankruptcy proceeding.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16"}},{"t":"case","label":"United States v. Wilson","cite":"503 U.S. 329","y":1992,"id":"1991/90-1745","sc":1,"sum":"It is the Attorney General who computes the amount of the § 3585(b) credit after the defendant has begun to serve his sentence.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30, 31"}},{"t":"case","label":"W.S. Peck Co. v. Lowenbein","cite":"178 F. 178","y":1910,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F./178/178/","by":{"0":"42"}},{"t":"case","label":"Wimberly v. Lab. & Indus. Rels. Comm’n","cite":"479 U.S. 511","y":1987,"id":"1986/85-129","sc":1,"sum":"The Missouri statute is consistent with the federal statute. The plain import of § 3304(a)(12)'s language is that Congress intended only to prohibit States from singling out pregnancy for unfavorable treatment and not to mandate preferential treatment. This is confirmed by both the legislative history and the Labor Department's interpretation of the statute. The focus of the statutory language is on the State's …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31"}},{"t":"usc","label":"11 U.S.C. § 101","url":"https://www.law.cornell.edu/uscode/text/11/101","subs":["(5)(A)","(12)","(31)","(41)"],"stext":{"head":"§101. Definitions","paras":[[0,"In this title the following definitions shall apply:"],[1,"(1) The term \"accountant\" means accountant authorized under applicable law to practice public accounting, and includes professional accounting association, corporation, or partnership, if so authorized."],[1,"(2) The term \"affiliate\" means—"],[2,"(A) entity that directly or indirectly owns, controls, or holds with power to vote, 20 percent or more of the outstanding voting securities of the debtor, other than an entity that holds such securities—"],[3,"(i) in a fiduciary or agency capacity without sole discretionary power to vote such securities; or"],[3,"(ii) solely to secure a debt, if such entity has not in fact exercised such power to vote;"],[2,"(B) corporation 20 percent or more of whose outstanding voting securities are directly or indirectly owned, controlled, or held with power to vote, by the debtor, or by an entity that directly or indirectly owns, controls, or holds with power to vote, 20 percent or more of the outstanding voting securities of the debtor, other than an entity that holds such securities—"],[3,"(i) in a fiduciary or agency capacity without sole discretionary power to vote such securities; or"],[3,"(ii) solely to secure a debt, if such entity has not in fact exercised such power to vote;"],[2,"(C) person whose business is operated under a lease or operating agreement by a debtor, or person substantially all of whose property is operated under an operating agreement with the debtor; or"],[2,"(D) entity that operates the business or substantially all of the property of the debtor under a lease or operating agreement."],[1,"(3) The term \"assisted person\" means any person whose debts consist primarily of consumer debts and the value of whose nonexempt property is less than $150,000.1"],[1,"(4) The term \"attorney\" means attorney, professional law association, corporation, or partnership, authorized under applicable law to practice law."],[1,"(4A) The term \"bankruptcy assistance\" means any goods or services sold or otherwise provided to an assisted person with the express or implied purpose of providing information, advice, counsel, document preparation, or filing, or attendance at a creditors' meeting or appearing in a case or proceeding on behalf of another or providing legal representation with respect to a case or proceeding under this title."],[1,"(5) The term \"claim\" means—"],[2,"(A) right to payment, whether or not such right is reduced to judgment, liquidated, unliquidated, fixed, contingent, matured, unmatured, disputed, undisputed, legal, equitable, secured, or unsecured; or"],[2,"(B) right to an equitable remedy for breach of performance if such breach gives rise to a right to payment, whether or not such right to an equitable remedy is reduced to judgment, fixed, contingent, matured, unmatured, disputed, undisputed, secured, or unsecured."],[1,"(6) The term \"commodity broker\" means futures commission merchant, foreign futures commission merchant, clearing organization, leverage transaction merchant, or commodity options dealer, as defined in section 761 of this title, with respect to which there is a customer, as defined in section 761 of this title."],[1,"(7) The term \"community claim\" means claim that arose before the commencement of the case concerning the debtor for which property of the kind specified in section 541(a)(2) of this title is liable, whether or not there is any such property at the time of the commencement of the case."],[1,"(7A) The term \"commercial fishing operation\" means—"],[2,"(A) the catching or harvesting of fish, shrimp, lobsters, urchins, seaweed, shellfish, or other aquatic species or products of such species; or"],[2,"(B) for purposes of section 109 and chapter 12, aquaculture activities consisting of raising for market any species or product described in subparagraph (A)."],[1,"(7B) The term \"commercial fishing vessel\" means a vessel used by a family fisherman to carry out a commercial fishing operation."],[1,"(8) The term \"consumer debt\" means debt incurred by an individual primarily for a personal, family, or household purpose."],[1,"(9) The term \"corporation\"—"],[2,"(A) includes—"],[3,"(i) association having a power or privilege that a private corporation, but not an individual or a partnership, possesses;"],[3,"(ii) partnership association organized under a law that makes only the capital subscribed responsible for the debts of such association;"],[3,"(iii) joint-stock company;"],[3,"(iv) unincorporated company or association; or"],[3,"(v) business trust; but"],[2,"(B) does not include limited partnership."],[1,"(10) The term \"creditor\" means—"],[2,"(A) entity that has a claim against the debtor that arose at the time of or before the order for relief concerning the debtor;"],[2,"(B) entity that has a claim against the estate of a kind specified in section 348(d), 502(f), 502(g), 502(h) or 502(i) of this title; or"],[2,"(C) entity that has a community claim."],[1,"(10A) The term \"current monthly income\"—"],[2,"(A) means the average monthly income from all sources that the debtor receives (or in a joint case the debtor and the debtor's spouse receive) without regard to whether such income is taxable income, derived during the 6-month period ending on—"],[3,"(i) the last day of the calendar month immediately preceding the date of the commencement of the case if the debtor files the schedule of current income required by section 521(a)(1)(B)(ii); or"],[3,"(ii) the date on which current income is determined by the court for purposes of this title if the debtor does not file the schedule of current income required by section 521(a)(1)(B)(ii); and"],[2,"(B)(i) includes any amount paid by any entity other than the debtor (or in a joint case the debtor and the debtor's spouse), on a regular basis for the household expenses of the debtor or the debtor's dependents (and in a joint case the debtor's spouse if not otherwise a dependent); and"],[2,"(ii) excludes—"],[3,"(I) benefits received under the Social Security Act (42 U.S.C. 301 et seq.);"],[3,"(II) payments to victims of war crimes or crimes against humanity on account of their status as victims of such crimes;"],[3,"(III) payments to victims of international terrorism or domestic terrorism, as those terms are defined in section 2331 of title 18, on account of their status as victims of such terrorism; and"],[3,"(IV) any monthly compensation, pension, pay, annuity, or allowance paid under title 10, 37, or 38 in connection with a disability, combat-related injury or disability, or death of a member of the uniformed services, except that any retired pay excluded under this subclause shall include retired pay paid under chapter 61 of title 10 only to the extent that such retired pay exceeds the amount of retired pay to which the debtor would otherwise be entitled if retired under any provision of title 10 other than chapter 61 of that title."],[1,"(11) The term \"custodian\" means—"],[2,"(A) receiver or trustee of any of the property of the debtor, appointed in a case or proceeding not under this title;"],[2,"(B) assignee under a general assignment for the benefit of the debtor's creditors; or"],[2,"(C) trustee, receiver, or agent under applicable law, or under a contract, that is appointed or authorized to take charge of property of the debtor for the purpose of enforcing a lien against such property, or for the purpose of general administration of such property for the benefit of the debtor's creditors."],[1,"(12) The term \"debt\" means liability on a claim."],[1,"(12A) The term \"debt relief agency\" means any person who provides any bankruptcy assistance to an assisted person in return for the payment of money or other valuable consideration, or who is a bankruptcy petition preparer under section 110, but does not include—"],[2,"(A) any person who is an officer, director, employee, or agent of a person who provides such assistance or of the bankruptcy petition preparer;"],[2,"(B) a nonprofit organization that is exempt from taxation under section 501(c)(3) of the Internal Revenue Code of 1986;"],[2,"(C) a creditor of such assisted person, to the extent that the creditor is assisting such assisted person to restructure any debt owed by such assisted person to the creditor;"],[2,"(D) a depository institution (as defined in section 3 of the Federal Deposit Insurance Act) or any Federal credit union or State credit union (as those terms are defined in section 101 of the Federal Credit Union Act), or any affiliate or subsidiary of such depository institution or credit union; or"],[2,"(E) an author, publisher, distributor, or seller of works subject to copyright protection under title 17, when acting in such capacity."],[1,"(13) The term \"debtor\" means person or municipality concerning which a case under this title has been commenced."],[1,"(13A) The term \"debtor's principal residence\"—"],[2,"(A) means a residential structure if used as the principal residence by the debtor, including incidental property, without regard to whether that structure is attached to real property; and"],[2,"(B) includes an individual condominium or cooperative unit, a mobile or manufactured home, or trailer if used as the principal residence by the debtor."],[1,"(14) The term \"disinterested person\" means a person that—"],[2,"(A) is not a creditor, an equity security holder, or an insider;"],[2,"(B) is not and was not, within 2 years before the date of the filing of the petition, a director, officer, or employee of the debtor; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/101?type=usc&year=mostrecent&link-type=html"},"head":"§101. Definitions","tname":"Bankruptcy","by":{"0":"18, 20, 34","1":"15, 15, 15, 35, 35","2":"1","3":"4"}},{"t":"usc","label":"18 U.S.C. § 3568","url":"https://www.law.cornell.edu/uscode/text/18/3568","subs":["(1982)"],"by":{"0":"30"}},{"t":"usc","label":"26 U.S.C. § 3304","url":"https://www.law.cornell.edu/uscode/text/26/3304","by":{"0":"31"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","by":{"0":"2"}},{"t":"usc","label":"42 U.S.C. § 3610","url":"https://www.law.cornell.edu/uscode/text/42/3610","subs":["(1976)"],"by":{"0":"33"}},{"t":"law","label":"Pub. L. No. 95-598","url":"https://www.govinfo.gov/link/statute/92/2549","by":{"0":"36, 37, 38","1":"22, 34","2":"21","3":"7"}},{"t":"case","label":"Ali v. Fed. Bureau of Prisons","cite":"552 U.S. 214","y":2008,"id":"2007/06-9130","sc":1,"sum":"The Court agreed with the 11th Circuit and, in a 5-4 majority opinion written by Justice Clarence Thomas, held that the use of the word \"any\" should be given its normal interpretation, encompassing all federal officers whether or not they were involved in enforcing customs or excise laws.","sumSrc":"Oyez","by":{"1":"17","2":"13"}},{"t":"case","label":"Andrus v. Glover Constr. Co.","cite":"446 U.S. 608","y":1980,"id":"1979/79-48","sc":1,"sum":"Held.: The Buy Indian Act, which permits the Secretary of the Interior to purchase \"the products of Indian industry... in open market,\" does not authorize the Department of the Interior's Bureau of Indian Affairs (BIA) to enter into road construction contracts with Indianowned companies without first advertising for bids pursuant to Title III of the Federal Property and Administrative Services Act of 1949 (FPASA). …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"17"}},{"t":"case","label":"Badgerow v. Walters","cite":"142 S. Ct. 1310","y":2022,"id":"2021/20-1143","sc":1,"op":1,"sum":"Federal jurisdiction in a petition to compel arbitration under Section 4 of the Federal Arbitration Act is determined by “looking through” the petition to the jurisdictional basis of the “underlying substantive controversy,” Vaden v. Discover Bank, 556 U. S. 49, 62, but that approach does not apply to petitions to confirm or vacate arbitral awards under Sections 9 and 10 of the FAA.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"40, 42"}},{"t":"case","label":"BedRoc Ltd., LLC v. United States","cite":"541 U.S. 176","y":2004,"id":"2003/02-1593","sc":1,"sum":"The Court ruled that because sand and gravel were not commercially valuable in 1919 when the Pittman Act was passed, they were not \"valuable minerals\" covered under the Act.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Bethune-Hill v. Va. State Bd. of Elections","cite":"137 S. Ct. 788","y":2017,"id":"2016/15-680","sc":1,"sum":"The Court determined that race can be shown to be the predominant factor in redistricting even when traditional principles are respected, and that district courts must engage in a holistic analysis.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"BFP v. Resol. Tr. Corp.","cite":"511 U.S. 531","y":1994,"id":"1993/92-1370","sc":1,"sum":"The Court ruled 5-4 that the value received for a property at a foreclosure sale can be reasonable even if it is different from the \"fair market value.\" A foreclosure sale alters market conditions and can lower a property's selling price.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"BP P.L.C. v. Mayor & City Council of Balt.","cite":"141 S. Ct. 1532","y":2021,"id":"2020/19-1189","sc":1,"sum":"Where defendant energy companies premised 28 U. S. C. §1447(d) removal in part on the federal officer removal statute, §1442, the Fourth Circuit erred in holding that it lacked jurisdiction to consider all grounds for removal rejected by the District Court.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"43"}},{"t":"case","label":"Brown v. Felsen","cite":"442 U.S. 127","y":1979,"id":"1978/78-58","sc":1,"ar":2,"sum":"The bankruptcy court is not confined to a review of the judgment and record in the prior state-court proceeding when determining the dischargeability of respondent's debt. When a debtor asserts the new defense of bankruptcy, res judicata does not bar the creditor from offering additional evidence to meet that defense. A contrary rule would force premature federal issues on the state courts and would frustrate the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22","2":"10, 17, 21, 29, 30","3":"11, 17, 18"}},{"t":"case","label":"Butner v. United States","cite":"440 U.S. 48","y":1979,"id":"1978/77-1410","sc":1,"sum":"Apart from certain special provisions, the Bankruptcy Act generally leaves the determination of property rights in the assets of a bankrupt's estate to BUTNER v. UNITED STATES","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21, 27"}},{"t":"case","label":"Chambers v. Kay","cite":"29 Cal. 4th 142","y":2002,"url":"https://www.courtlistener.com/c/Cal.%204th/29/142/","by":{"1":"4"}},{"t":"case","label":"City & County of San Francisco v. Sheehan","cite":"575 U.S. 600","y":2015,"id":"2014/13-1412","sc":1,"op":1,"sum":"The Court held that an unwarranted entry does not violate the Fourth Amendment when it does not violate a clearly established constitutional or statutory right and is reasonable under the circumstances.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"sum":"The Court said the requirement that immigrants be detained no longer than reasonably necessary for deportation applied to both admissible and inadmissible immigrants. Because readmission to Cuba was unforeseeable, the detentions of Martinez and Benitez were unreasonable.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"Dean v. United States","cite":"556 U.S. 568","y":2009,"id":"2008/08-5274","sc":1,"op":1,"ar":1,"sum":"The Court held that 18 U.S.C. Section 924(c)(1)(A)(iii) does not require proof of intent to discharge a firearm in order to enhance a sentence.","sumSrc":"Oyez","by":{"1":"36","2":"16"}},{"t":"case","label":"(v) Deodati v. M.M. Winkler & Assocs. (In re M.M. Winkler & Assocs.)","cite":"239 F.3d 746","y":2001,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/239/746/","op":1,"by":{"1":"18"}},{"t":"case","label":"Dodd v. United States","cite":"545 U.S. 353","y":2005,"id":"2004/04-5286","sc":1,"sum":"The Court held that the text of the federal law \"unequivocally\" stated that the one-year limitation period begins to run on the date on which the Court \"initially recongized\" the right, not the date on which that right was made retroactive.","sumSrc":"Oyez","by":{"1":"23"}},{"t":"case","label":"Encino Motorcars, LLC v. Navarro","cite":"138 S. Ct. 1134","y":2018,"id":"2017/16-1362","sc":1,"sum":"The Court decided that because service advisors at car dealerships are “salesm[e]n . . . primarily engaged in . . . servicing automobiles,” 29 U.S.C. § 213(b)(10)(A), they are exempt from the Fair Labor Standards Act's overtime-pay requirements.","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"Food Mktg. Inst. v. Argus Leader Media","cite":"139 S. Ct. 2356","y":2019,"id":"2018/18-481","sc":1,"sum":"Where commercial or financial information is both customarily and actually treated as private by its owner and provided to the government under an assurance of privacy, the information is “confidential” within the meaning of 5 U. S. C. §552(b)(4), the Freedom of Information Act’s Exemption 4.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"33"}},{"t":"case","label":"Gallardo v. Marstiller","cite":"142 S. Ct. 1751","y":2022,"id":"2021/20-1263","sc":1,"sum":"The Medicaid Act permits a State to seek reimbursement from settlement payments allocated for future medical care.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"17"}},{"t":"case","label":"Garcia v. Vanguard Car Rental USA, Inc.","cite":"540 F.3d 1242","y":2008,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/540/1242/","by":{"1":"24"}},{"t":"case","label":"Gleason v. Seaboard Air Line Ry. Co.","cite":"278 U.S. 349","y":1929,"id":"scdb/1928-040","sc":1,"sum":"that the'railway company was liable for the deceit.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"27"}},{"t":"case","label":"Gleason v. Thaw","cite":"236 U.S. 558","y":1915,"id":"scdb/1914-236","sc":1,"op":1,"sum":"Professional services of an attorney and counselor-at-law are not property within the meaning of par..2, § 17 of the Bankruptcy Act of 1898, as amended in 1903, excepting liabilities for obtaining property by false pretenses from the general release of the discharge in bankruptcy.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"32, 33"}},{"t":"case","label":"Hillman v. Maretta","cite":"569 U.S. 483","y":2013,"id":"2012/11-1221","sc":1,"op":1,"sum":"The Court found that the Federal Employees' Group Life Insurance Act preempts a Virginia state law regarding beneficiary designation upon divorce.","sumSrc":"Oyez","by":{"1":"17","2":"14"}},{"t":"case","label":"Kloeckner v. Solis","cite":"568 U.S. 41","y":2012,"id":"2012/11-184","sc":1,"sum":"The Court found that the district court, rather than the Court of Appeals, has jurisdiction over \"mixed\" cases that have been dismissed by the Merit Systems Protection Board.","sumSrc":"Oyez","by":{"1":"43"}},{"t":"case","label":"(vi) Mary M. v. City of Los Angeles","cite":"54 Cal. 3d 202","y":1991,"url":"https://www.courtlistener.com/c/Cal.%203d/54/202/","by":{"1":"28"}},{"t":"case","label":"McIntyre v. Kavanaugh","cite":"242 U.S. 138","y":1916,"id":"scdb/1916-031","sc":1,"sum":"Partners are individually responsible for torts committed by their firm while acting within the general scope of its business, whether they personally participate therein or not.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"20, 25","2":"23","3":"24"}},{"t":"case","label":"Meyer v. Holley","cite":"537 U.S. 280","y":2003,"id":"2002/01-1120","sc":1,"ar":2,"sum":"The Court held that the FHA imposes liability without fault upon the employer in accordance with traditional agency principles. In other words, the FHA normally imposes vicarious liability upon the corporation, but not upon its officers or owners.","sumSrc":"Oyez","by":{"1":"passim","3":"20, 21"}},{"t":"case","label":"Milavetz, Gallop & Milavetz, P.A. v. United States","cite":"559 U.S. 229","y":2010,"id":"2009/08-1119","sc":1,"sum":"The Court held that attorneys who provide bankruptcy assistance are debt relief agencies under the Bankruptcy Abuse Prevention and Consumer Protection Act.","sumSrc":"Oyez","by":{"1":"20","2":"27","3":"6, 24"}},{"t":"case","label":"Miske v. Coxeter","cite":"204 Cal. App. 4th 1249","y":2012,"url":"https://www.courtlistener.com/c/Cal.%20App.%204th/204/1249/","by":{"1":"4, 27, 39"}},{"t":"case","label":"Morgan v. Sundance","cite":"142 S. Ct. 1708","y":2022,"id":"2021/21-328","sc":1,"sum":"Federal courts may not adopt an arbitration-specific rule conditioning a waiver of the right to arbitrate on a showing of prejudice.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"30"}},{"t":"case","label":"Murphy v. Smith","cite":"138 S. Ct. 784","y":2018,"id":"2017/16-1067","sc":1,"sum":"A case in which the Court interpreted the parenthetical phrase “not to exceed 25 percent,” as used in 42 U.S.C. § 1997e(d)(2), to mean exactly 25 percent, thereby precluding the district court from exercising its discretion to allocate a lower percentage of the damage award to attorney's fees.","sumSrc":"Oyez","by":{"1":"37"}},{"t":"case","label":"Nat’l Ass’n of Mfrs. v. Dep’t of Def.","cite":"138 S. Ct. 617","y":2018,"id":"2017/16-299","sc":1,"sum":"The Court decided that challenges to the Environmental Protection Agency’s rule that defines the scope of United States waters must be filed in federal district courts.","sumSrc":"Oyez","by":{"1":"13, 24"}},{"t":"case","label":"New Orleans, M., & C.R. Co. v. Hanning","cite":"82 U.S. 649","y":1872,"id":"scdb/1872-125","sc":1,"sum":"The New Orleans, Mobile, and Chattanooga Railroad Company — the station-house grounds of whose road in New Orleans came down in one part of the city to the batture of the Mississippi — obtained conveyances of the batture property in front, the same being accurately described by maps annexed to them, and were desirous of building in front of their batture a wharf on the river, and also of repairing an old wharf there.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"5"}},{"t":"case","label":"OBB Personenverkehr AG v. Sachs","cite":"577 U.S. 27","y":2015,"id":"2015/13-1067","sc":1,"sum":"The Court held that the commercial activity exception to the Foreign Sovereign Immunity Act only applies when the suit is based upon activity that took place in the United States, and it was not sufficient to establish a single element of the claim in question.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"Oklahoma v. Castro-Huerta","cite":"142 S. Ct. 2486","y":2022,"id":"2021/21-429","sc":1,"sum":"The Federal Government and the State have concurrent jurisdiction to prosecute crimes committed by non-Indians against Indians in Indian country.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"34"}},{"t":"case","label":"Pa. Dep’t of Pub. Welfare v. Davenport","cite":"495 U.S. 552","y":1990,"id":"1989/89-156","sc":1,"sum":"The Code's language and structure demonstrate that restitution obligations constitute \"debts\" within the meaning of § 101(11) and are therefore dischargeable under Chapter 13.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"15, 21"}},{"t":"case","label":"Pac. Mut. Life Ins. Co. v. Haslip","cite":"499 U.S. 1","y":1991,"id":"1990/89-1279","sc":1,"sum":"The punitive damages award in this case did not violate the Due Process Clause of the Fourteenth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"27"}},{"t":"case","label":"Puerto Rico v. Franklin Cal. Tax-Free Tr.","cite":"579 U.S. 115","y":2016,"id":"2015/15-233","sc":1,"sum":"The Court determined that Chapter 9 of the Bankruptcy Code preempted the Puerto Rico statute that allowed public utilities to restructure their debt.","sumSrc":"Oyez","by":{"1":"23"}},{"t":"case","label":"(vii) RadLAX Gateway Hotel, LLC v. Amalgamated Bank","cite":"566 U.S. 639","y":2012,"id":"2011/11-166","sc":1,"sum":"The Court held that a company could not obtain confirmation of a Chapter 11 bankruptcy plan that provided for the sale of its assets free from lien without permitting a bank to credit-bid at the sale.","sumSrc":"Oyez","by":{"1":"44"}},{"t":"case","label":"Siebold v. Berdine","cite":"61 Cal. App. 158","y":1923,"url":"https://www.courtlistener.com/c/Cal.%20App./61/158/","by":{"1":"4"}},{"t":"case","label":"Sullivan v. Glenn","cite":"782 F.3d 378","y":2015,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/782/378/","op":1,"by":{"1":"29, 30, 31"}},{"t":"case","label":"Tapia v. United States","cite":"564 U.S. 319","y":2011,"id":"2010/10-5400","sc":1,"sum":"The Court held that a district court may not give a defendant a longer prison sentence based on speculation about if and when the defendant would be able to participate in an inmate drug rehabilitation program.","sumSrc":"Oyez","by":{"1":"13"}},{"t":"case","label":"United States v. Boyle","cite":"469 U.S. 241","y":1985,"id":"1984/83-1266","sc":1,"sum":"The failure to make a timely filing of a tax return is not excused by the taxpayer's reliance on an agent, and such reliance is not \"reasonable cause\" for a late filing under §6651(a)(1). While engaging an attorney to assist in probate proceedings is plainly an exercise of the \"ordinary business care and prudence\" that the relevant Treasury Regulation requires the taxpayer to demonstrate to excuse a late filing, …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"41"}},{"t":"case","label":"United States v. Gonzales","cite":"520 U.S. 1","y":1997,"id":"1996/95-1605","sc":1,"sum":"In a 7-to-2 decision delivered by Justice Sandra Day O'Connor, the Court announced \"[t]he plain language of (the law) forbids a district court to direct that a term of imprisonment under the statute run concurrently with any other term of imprisonment, whether state or federal.\".","sumSrc":"Oyez","by":{"1":"16","2":"13"}},{"t":"case","label":"United States v. Jones","cite":"565 U.S. 400","y":2012,"id":"2011/10-1259","sc":1,"sum":"The Court found that a police department's placement of a GPS tracking device on a man's Jeep without his knowledge was an illegal search under the Fourth Amendment.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"United States v. Texas","cite":"507 U.S. 529","y":1993,"id":"1992/91-1729","sc":1,"op":1,"sum":"The Act left in place the States' federal common-law obligation to pay prejudgment interest on debts owed to the Federal Government.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"Van Buren v. United States","cite":"141 S. Ct. 1648","y":2021,"id":"2020/19-783","sc":1,"op":1,"sum":"An individual “exceeds authorized access” under the Computer Fraud and Abuse Act of 1986, 18 U. S. C. §1030(a)(2), when he accesses a computer with authorization but then obtains information located in particular areas of the computer—such as files, folders, or databases—that are off-limits to him.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"31"}},{"t":"case","label":"Veritex Cmty. Bank v. Osborne (In re Osborne)","cite":"951 F.3d 691","y":2020,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/951/691/","by":{"1":"25, 41","3":"8"}},{"t":"case","label":"Visa Inc. v. Osborn","cite":"137 S. Ct. 289","y":2016,"id":"2016/15-961","sc":1,"sum":"A case in which the Court would have determined whether allegations that members of a business organization agreed to adhere to the organization’s rules and possessed governance rights to the organization are sufficient to plead that there was a conspiracy under the Sherman Act.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"Walker v. Citizens State Bank (In re Walker)","cite":"726 F.2d 452","y":1984,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/726/452/","op":1,"by":{"1":"29, 30, 31","2":"23"}},{"t":"case","label":"Watson v. United States","cite":"552 U.S. 74","y":2007,"id":"2007/06-571","sc":1,"op":1,"by":{"1":"36","2":"16"}},{"t":"case","label":"(viii) Whitfield v. United States","cite":"574 U.S. 265","y":2015,"id":"2014/13-9026","sc":1,"sum":"The Court held that forced accompaniment during the commission of a crime occurs when a person requires another to “go with” him, even when that movement occurs over a short distance.","sumSrc":"Oyez","by":{"1":"9, 17"}},{"t":"usc","label":"1 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/1/1","by":{"1":"12, 35"}},{"t":"usc","label":"11 U.S.C. § 110","url":"https://www.law.cornell.edu/uscode/text/11/110","by":{"1":"41"}},{"t":"usc","label":"11 U.S.C. § 365","url":"https://www.law.cornell.edu/uscode/text/11/365","by":{"1":"24"}},{"t":"usc","label":"11 U.S.C. § 523","url":"https://www.law.cornell.edu/uscode/text/11/523","subs":["(a)(1)","(a)(2)(A)","(a)(2)(B)","(a)(2)(C)","(a)(3)","(a)(6)","(a)(13)","(a)(14)","(a)(14A)","(a)(14B)","(a)(19)(B)","(a)","(a)(1)(C)","(a)(2)","(a)(2)(B)(iv)","(a)(2)(C)(i)","(a)(2)(C)(i)(I)","(a)(2)(C)(i)(II)","(a)(4)","(a)(9)","(a)(12)","(a)(15)","(a)(18)"],"stext":{"head":"§523. Exceptions to discharge","paras":[[0,"(a) A discharge under section 727, 1141, 1192 1 1228(a), 1228(b), or 1328(b) of this title does not discharge an individual debtor from any debt—"],[1,"(1) for a tax or a customs duty—"],[2,"(A) of the kind and for the periods specified in section 507(a)(3) or 507(a)(8) of this title, whether or not a claim for such tax was filed or allowed;"],[2,"(B) with respect to which a return, or equivalent report or notice, if required—"],[3,"(i) was not filed or given; or"],[3,"(ii) was filed or given after the date on which such return, report, or notice was last due, under applicable law or under any extension, and after two years before the date of the filing of the petition; or"],[2,"(C) with respect to which the debtor made a fraudulent return or willfully attempted in any manner to evade or defeat such tax;"],[1,"(2) for money, property, services, or an extension, renewal, or refinancing of credit, to the extent obtained by—"],[2,"(A) false pretenses, a false representation, or actual fraud, other than a statement respecting the debtor's or an insider's financial condition;"],[2,"(B) use of a statement in writing—"],[3,"(i) that is materially false;"],[3,"(ii) respecting the debtor's or an insider's financial condition;"],[3,"(iii) on which the creditor to whom the debtor is liable for such money, property, services, or credit reasonably relied; and"],[3,"(iv) that the debtor caused to be made or published with intent to deceive; or"],[2,"(C)(i) for purposes of subparagraph (A)—"],[3,"(I) consumer debts owed to a single creditor and aggregating more than $500 2 for luxury goods or services incurred by an individual debtor on or within 90 days before the order for relief under this title are presumed to be nondischargeable; and"],[3,"(II) cash advances aggregating more than $750 2 that are extensions of consumer credit under an open end credit plan obtained by an individual debtor on or within 70 days before the order for relief under this title, are presumed to be nondischargeable; and"],[2,"(ii) for purposes of this subparagraph—"],[3,"(I) the terms \"consumer\", \"credit\", and \"open end credit plan\" have the same meanings as in section 103 of the Truth in Lending Act; and"],[3,"(II) the term \"luxury goods or services\" does not include goods or services reasonably necessary for the support or maintenance of the debtor or a dependent of the debtor;"],[1,"(3) neither listed nor scheduled under section 521(a)(1) of this title, with the name, if known to the debtor, of the creditor to whom such debt is owed, in time to permit—"],[2,"(A) if such debt is not of a kind specified in paragraph (2), (4), or (6) of this subsection, timely filing of a proof of claim, unless such creditor had notice or actual knowledge of the case in time for such timely filing; or"],[2,"(B) if such debt is of a kind specified in paragraph (2), (4), or (6) of this subsection, timely filing of a proof of claim and timely request for a determination of dischargeability of such debt under one of such paragraphs, unless such creditor had notice or actual knowledge of the case in time for such timely filing and request;"],[1,"(4) for fraud or defalcation while acting in a fiduciary capacity, embezzlement, or larceny;"],[1,"(5) for a domestic support obligation;"],[1,"(6) for willful and malicious injury by the debtor to another entity or to the property of another entity;"],[1,"(7) to the extent such debt is for a fine, penalty, or forfeiture payable to and for the benefit of a governmental unit, and is not compensation for actual pecuniary loss, other than a tax penalty—"],[2,"(A) relating to a tax of a kind not specified in paragraph (1) of this subsection; or"],[2,"(B) imposed with respect to a transaction or event that occurred before three years before the date of the filing of the petition;"],[1,"(8) unless excepting such debt from discharge under this paragraph would impose an undue hardship on the debtor and the debtor's dependents, for—"],[2,"(A)(i) an educational benefit overpayment or loan made, insured, or guaranteed by a governmental unit, or made under any program funded in whole or in part by a governmental unit or nonprofit institution; or"],[2,"(ii) an obligation to repay funds received as an educational benefit, scholarship, or stipend; or"],[2,"(B) any other educational loan that is a qualified education loan, as defined in section 221(d)(1) of the Internal Revenue Code of 1986, incurred by a debtor who is an individual;"],[1,"(9) for death or personal injury caused by the debtor's operation of a motor vehicle, vessel, or aircraft if such operation was unlawful because the debtor was intoxicated from using alcohol, a drug, or another substance;"],[1,"(10) that was or could have been listed or scheduled by the debtor in a prior case concerning the debtor under this title or under the Bankruptcy Act in which the debtor waived discharge, or was denied a discharge under section 727(a)(2), (3), (4), (5), (6), or (7) of this title, or under section 14c(1), (2), (3), (4), (6), or (7) of such Act;"],[1,"(11) provided in any final judgment, unreviewable order, or consent order or decree entered in any court of the United States or of any State, issued by a Federal depository institutions regulatory agency, or contained in any settlement agreement entered into by the debtor, arising from any act of fraud or defalcation while acting in a fiduciary capacity committed with respect to any depository institution or insured credit union;"],[1,"(12) for malicious or reckless failure to fulfill any commitment by the debtor to a Federal depository institutions regulatory agency to maintain the capital of an insured depository institution, except that this paragraph shall not extend any such commitment which would otherwise be terminated due to any act of such agency;"],[1,"(13) for any payment of an order of restitution issued under title 18, United States Code;"],[1,"(14) incurred to pay a tax to the United States that would be nondischargeable pursuant to paragraph (1);"],[1,"(14A) incurred to pay a tax to a governmental unit, other than the United States, that would be nondischargeable under paragraph (1);"],[1,"(14B) incurred to pay fines or penalties imposed under Federal election law;"],[1,"(15) to a spouse, former spouse, or child of the debtor and not of the kind described in paragraph (5) that is incurred by the debtor in the course of a divorce or separation or in connection with a separation agreement, divorce decree or other order of a court of record, or a determination made in accordance with State or territorial law by a governmental unit;"],[1,"(16) for a fee or assessment that becomes due and payable after the order for relief to a membership association with respect to the debtor's interest in a unit that has condominium ownership, in a share of a cooperative corporation, or a lot in a homeowners association, for as long as the debtor or the trustee has a legal, equitable, or possessory ownership interest in such unit, such corporation, or such lot, but nothing in this paragraph shall except from discharge the debt of a debtor for a membership association fee or assessment for a period arising before entry of the order for relief in a pending or subsequent bankruptcy case;"],[1,"(17) for a fee imposed on a prisoner by any court for the filing of a case, motion, complaint, or appeal, or for other costs and expenses assessed with respect to such filing, regardless of an assertion of poverty by the debtor under subsection (b) or (f)(2) of section 1915 of title 28 (or a similar non-Federal law), or the debtor's status as a prisoner, as defined in section 1915(h) of title 28 (or a similar non-Federal law);"],[1,"(18) owed to a pension, profit-sharing, stock bonus, or other plan established under section 401, 403, 408, 408A, 414, 457, or 501(c) of the Internal Revenue Code of 1986, under—"],[2,"(A) a loan permitted under section 408(b)(1) of the Employee Retirement Income Security Act of 1974, or subject to section 72(p) of the Internal Revenue Code of 1986; or"],[2,"(B) a loan from a thrift savings plan permitted under subchapter III of chapter 84 of title 5, that satisfies the requirements of section 8433(g) of such title;"],[1,"but nothing in this paragraph may be construed to provide that any loan made under a governmental plan under section 414(d), or a contract or account under section 403(b), of the Internal Revenue Code of 1986 constitutes a claim or a debt under this title;"],[1,"(19) that—"],[2,"(A) is for—"],[3,"(i) the violation of any of the Federal securities laws (as that term is defined in section 3(a)(47) of the Securities Exchange Act of 1934), any of the State securities laws, or any regulation or order issued under such Federal or State securities laws; or"],[3,"(ii) common law fraud, deceit, or manipulation in connection with the purchase or sale of any security; and"],[2,"(B) results, before, on, or after the date on which the petition was filed, from—"],[3,"(i) any judgment, order, consent order, or decree entered in any Federal or State judicial or administrative proceeding;"],[3,"(ii) any settlement agreement entered into by the debtor; or"],[3,"(iii) any court or administrative order for any damages, fine, penalty, citation, restitutionary payment, disgorgement payment, attorney fee, cost, or other payment owed by the debtor; or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/523?type=usc&year=mostrecent&link-type=html"},"op":2,"ar":1,"head":"§523. Exceptions to discharge","tname":"Bankruptcy","by":{"1":"6, 41, passim, passim, 39, 40, 41, 25, 25, 41, 41, 26, 26","2":"3, 4, 6, 10, 24, 3, 4, 6, 10, 24, 3, 4, 6, 10, 24, 3, 4, 6, 10, 24, 3, 4, 6, 10, 24, 3, 4, 6, 10, 24, 3, 4, 6, 10, 24, 3, 4, 6, 10, 24, 3, 4, 6, 10, 24, 3, 4, 6, 10, 24, 3, 4, 6, 10, 24, 3, 4, 6, 10, 24, 3, 4, 6, 10, 24, 3, 4, 6, 10, 24, 3, 4, 6, 10, 24, 3, 4, 6, 10, 24, 3, 4, 6, 10, 24, 3, 4, 6, 10, 24, 3, 4, 6, 10, 24, 3, 4, 6, 10, 24, 3, 4, 6, 10, 24"}},{"t":"usc","label":"11 U.S.C. § 727","url":"https://www.law.cornell.edu/uscode/text/11/727","subs":["(a)","(a)(2)"],"stext":{"head":"§727. Discharge","paras":[[0,"(a) The court shall grant the debtor a discharge, unless—"],[1,"(1) the debtor is not an individual;"],[1,"(2) the debtor, with intent to hinder, delay, or defraud a creditor or an officer of the estate charged with custody of property under this title, has transferred, removed, destroyed, mutilated, or concealed, or has permitted to be transferred, removed, destroyed, mutilated, or concealed—"],[2,"(A) property of the debtor, within one year before the date of the filing of the petition; or"],[2,"(B) property of the estate, after the date of the filing of the petition;"],[1,"(3) the debtor has concealed, destroyed, mutilated, falsified, or failed to keep or preserve any recorded information, including books, documents, records, and papers, from which the debtor's financial condition or business transactions might be ascertained, unless such act or failure to act was justified under all of the circumstances of the case;"],[1,"(4) the debtor knowingly and fraudulently, in or in connection with the case—"],[2,"(A) made a false oath or account;"],[2,"(B) presented or used a false claim;"],[2,"(C) gave, offered, received, or attempted to obtain money, property, or advantage, or a promise of money, property, or advantage, for acting or forbearing to act; or"],[2,"(D) withheld from an officer of the estate entitled to possession under this title, any recorded information, including books, documents, records, and papers, relating to the debtor's property or financial affairs;"],[1,"(5) the debtor has failed to explain satisfactorily, before determination of denial of discharge under this paragraph, any loss of assets or deficiency of assets to meet the debtor's liabilities;"],[1,"(6) the debtor has refused, in the case—"],[2,"(A) to obey any lawful order of the court, other than an order to respond to a material question or to testify;"],[2,"(B) on the ground of privilege against self-incrimination, to respond to a material question approved by the court or to testify, after the debtor has been granted immunity with respect to the matter concerning which such privilege was invoked; or"],[2,"(C) on a ground other than the properly invoked privilege against self-incrimination, to respond to a material question approved by the court or to testify;"],[1,"(7) the debtor has committed any act specified in paragraph (2), (3), (4), (5), or (6) of this subsection, on or within one year before the date of the filing of the petition, or during the case, in connection with another case, under this title or under the Bankruptcy Act, concerning an insider;"],[1,"(8) the debtor has been granted a discharge under this section, under section 1141 of this title, or under section 14, 371, or 476 of the Bankruptcy Act, in a case commenced within 8 years before the date of the filing of the petition;"],[1,"(9) the debtor has been granted a discharge under section 1228 or 1328 of this title, or under section 660 or 661 of the Bankruptcy Act, in a case commenced within six years before the date of the filing of the petition, unless payments under the plan in such case totaled at least—"],[2,"(A) 100 percent of the allowed unsecured claims in such case; or"],[2,"(B)(i) 70 percent of such claims; and"],[2,"(ii) the plan was proposed by the debtor in good faith, and was the debtor's best effort;"],[1,"(10) the court approves a written waiver of discharge executed by the debtor after the order for relief under this chapter;"],[1,"(11) after filing the petition, the debtor failed to complete an instructional course concerning personal financial management described in section 111, except that this paragraph shall not apply with respect to a debtor who is a person described in section 109(h)(4) or who resides in a district for which the United States trustee (or the bankruptcy administrator, if any) determines that the approved instructional courses are not adequate to service the additional individuals who would otherwise be required to complete such instructional courses under this section (The United States trustee (or the bankruptcy administrator, if any) who makes a determination described in this paragraph shall review such determination not later than 1 year after the date of such determination, and not less frequently than annually thereafter.); or"],[1,"(12) the court after notice and a hearing held not more than 10 days before the date of the entry of the order granting the discharge finds that there is reasonable cause to believe that—"],[2,"(A) section 522(q)(1) may be applicable to the debtor; and"],[2,"(B) there is pending any proceeding in which the debtor may be found guilty of a felony of the kind described in section 522(q)(1)(A) or liable for a debt of the kind described in section 522(q)(1)(B)."],[0,"(b) Except as provided in section 523 of this title, a discharge under subsection (a) of this section discharges the debtor from all debts that arose before the date of the order for relief under this chapter, and any liability on a claim that is determined under section 502 of this title as if such claim had arisen before the commencement of the case, whether or not a proof of claim based on any such debt or liability is filed under section 501 of this title, and whether or not a claim based on any such debt or liability is allowed under section 502 of this title."],[0,"(c)(1) The trustee, a creditor, or the United States trustee may object to the granting of a discharge under subsection (a) of this section."],[0,"(2) On request of a party in interest, the court may order the trustee to examine the acts and conduct of the debtor to determine whether a ground exists for denial of discharge."],[0,"(d) On request of the trustee, a creditor, or the United States trustee, and after notice and a hearing, the court shall revoke a discharge granted under subsection (a) of this section if—"],[1,"(1) such discharge was obtained through the fraud of the debtor, and the requesting party did not know of such fraud until after the granting of such discharge;"],[1,"(2) the debtor acquired property that is property of the estate, or became entitled to acquire property that would be property of the estate, and knowingly and fraudulently failed to report the acquisition of or entitlement to such property, or to deliver or surrender such property to the trustee;"],[1,"(3) the debtor committed an act specified in subsection (a)(6) of this section; or"],[1,"(4) the debtor has failed to explain satisfactorily—"],[2,"(A) a material misstatement in an audit referred to in section 586(f) of title 28; or"],[2,"(B) a failure to make available for inspection all necessary accounts, papers, documents, financial records, files, and all other papers, things, or property belonging to the debtor that are requested for an audit referred to in section 586(f) of title 28."],[0,"(e) The trustee, a creditor, or the United States trustee may request a revocation of a discharge—"],[1,"(1) under subsection (d)(1) of this section within one year after such discharge is granted; or"],[1,"(2) under subsection (d)(2) or (d)(3) of this section before the later of—"],[2,"(A) one year after the granting of such discharge; and"],[2,"(B) the date the case is closed."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/727?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§727. Discharge","tname":"Bankruptcy","by":{"1":"6","2":"3, 24, 3, 24, 3, 24"}},{"t":"usc","label":"11 U.S.C. § 1141","url":"https://www.law.cornell.edu/uscode/text/11/1141","subs":["(d)(6)(A)","(d)(2)","(d)(6)"],"stext":{"head":"§1141. Effect of confirmation","paras":[[0,"(a) Except as provided in subsections (d)(2) and (d)(3) of this section, the provisions of a confirmed plan bind the debtor, any entity issuing securities under the plan, any entity acquiring property under the plan, and any creditor, equity security holder, or general partner in the debtor, whether or not the claim or interest of such creditor, equity security holder, or general partner is impaired under the plan and whether or not such creditor, equity security holder, or general partner has accepted the plan."],[0,"(b) Except as otherwise provided in the plan or the order confirming the plan, the confirmation of a plan vests all of the property of the estate in the debtor."],[0,"(c) Except as provided in subsections (d)(2) and (d)(3) of this section and except as otherwise provided in the plan or in the order confirming the plan, after confirmation of a plan, the property dealt with by the plan is free and clear of all claims and interests of creditors, equity security holders, and of general partners in the debtor."],[0,"(d)(1) Except as otherwise provided in this subsection, in the plan, or in the order confirming the plan, the confirmation of a plan—"],[1,"(A) discharges the debtor from any debt that arose before the date of such confirmation, and any debt of a kind specified in section 502(g), 502(h), or 502(i) of this title, whether or not—"],[2,"(i) a proof of the claim based on such debt is filed or deemed filed under section 501 of this title;"],[2,"(ii) such claim is allowed under section 502 of this title; or"],[2,"(iii) the holder of such claim has accepted the plan; and"],[1,"(B) terminates all rights and interests of equity security holders and general partners provided for by the plan."],[0,"(2) A discharge under this chapter does not discharge a debtor who is an individual from any debt excepted from discharge under section 523 of this title."],[0,"(3) The confirmation of a plan does not discharge a debtor if—"],[1,"(A) the plan provides for the liquidation of all or substantially all of the property of the estate;"],[1,"(B) the debtor does not engage in business after consummation of the plan; and"],[1,"(C) the debtor would be denied a discharge under section 727(a) of this title if the case were a case under chapter 7 of this title."],[0,"(4) The court may approve a written waiver of discharge executed by the debtor after the order for relief under this chapter."],[0,"(5) In a case in which the debtor is an individual—"],[1,"(A) unless after notice and a hearing the court orders otherwise for cause, confirmation of the plan does not discharge any debt provided for in the plan until the court grants a discharge on completion of all payments under the plan;"],[1,"(B) at any time after the confirmation of the plan, and after notice and a hearing, the court may grant a discharge to the debtor who has not completed payments under the plan if—"],[2,"(i) the value, as of the effective date of the plan, of property actually distributed under the plan on account of each allowed unsecured claim is not less than the amount that would have been paid on such claim if the estate of the debtor had been liquidated under chapter 7 on such date;"],[2,"(ii) modification of the plan under section 1127 is not practicable; and"],[2,"(iii) subparagraph (C) permits the court to grant a discharge; and"],[1,"(C) the court may grant a discharge if, after notice and a hearing held not more than 10 days before the date of the entry of the order granting the discharge, the court finds that there is no reasonable cause to believe that—"],[2,"(i) section 522(q)(1) may be applicable to the debtor; and"],[2,"(ii) there is pending any proceeding in which the debtor may be found guilty of a felony of the kind described in section 522(q)(1)(A) or liable for a debt of the kind described in section 522(q)(1)(B);"],[1,"and if the requirements of subparagraph (A) or (B) are met."],[1,"(6) Notwithstanding paragraph (1), the confirmation of a plan does not discharge a debtor that is a corporation from any debt—"],[2,"(A) of a kind specified in paragraph (2)(A) or (2)(B) of section 523(a) that is owed to a domestic governmental unit, or owed to a person as the result of an action filed under subchapter III of chapter 37 of title 31 or any similar State statute; or"],[2,"(B) for a tax or customs duty with respect to which the debtor—"],[3,"(i) made a fraudulent return; or"],[3,"(ii) willfully attempted in any manner to evade or to defeat such tax or such customs duty."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/1141?type=usc&year=mostrecent&link-type=html"},"head":"§1141. Effect of confirmation","tname":"Bankruptcy","by":{"1":"14, 35","2":"24, 24"}},{"t":"usc","label":"11 U.S.C. § 1305","url":"https://www.law.cornell.edu/uscode/text/11/1305","subs":["(c)"],"by":{"1":"30"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(d)(1)"],"by":{"1":"36"}},{"t":"usc","label":"49 U.S.C. § 30106","url":"https://www.law.cornell.edu/uscode/text/49/30106","stext":{"head":"§30106. Rented or leased motor vehicle safety and responsibility","paras":[[0,"(a) In General.—An owner of a motor vehicle that rents or leases the vehicle to a person (or an affiliate of the owner) shall not be liable under the law of any State or political subdivision thereof, by reason of being the owner of the vehicle (or an affiliate of the owner), for harm to persons or property that results or arises out of the use, operation, or possession of the vehicle during the period of the rental or lease, if—"],[1,"(1) the owner (or an affiliate of the owner) is engaged in the trade or business of renting or leasing motor vehicles; and"],[1,"(2) there is no negligence or criminal wrongdoing on the part of the owner (or an affiliate of the owner)."],[0,"(b) Financial Responsibility Laws.—Nothing in this section supersedes the law of any State or political subdivision thereof—"],[1,"(1) imposing financial responsibility or insurance standards on the owner of a motor vehicle for the privilege of registering and operating a motor vehicle; or"],[1,"(2) imposing liability on business entities engaged in the trade or business of renting or leasing motor vehicles for failure to meet the financial responsibility or liability insurance requirements under State law."],[0,"(c) Applicability and Effective Date.—Notwithstanding any other provision of law, this section shall apply with respect to any action commenced on or after the date of enactment of this section without regard to whether the harm that is the subject of the action, or the conduct that caused the harm, occurred before such date of enactment."],[0,"(d) Definitions.—In this section, the following definitions apply:"],[1,"(1) Affiliate.—The term \"affiliate\" means a person other than the owner that directly or indirectly controls, is controlled by, or is under common control with the owner. In the preceding sentence, the term \"control\" means the power to direct the management and policies of a person whether through ownership of voting securities or otherwise."],[1,"(2) Owner.—The term \"owner\" means a person who is—"],[2,"(A) a record or beneficial owner, holder of title, lessor, or lessee of a motor vehicle;"],[2,"(B) entitled to the use and possession of a motor vehicle subject to a security interest in another person; or"],[2,"(C) a lessor, lessee, or a bailee of a motor vehicle, in the trade or business of renting or leasing motor vehicles, having the use or possession thereof, under a lease, bailment, or otherwise."],[1,"(3) Person.—The term \"person\" means any individual, corporation, company, limited liability company, trust, association, firm, partnership, society, joint stock company, or any other entity."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/49/30106?type=usc&year=mostrecent&link-type=html"},"head":"§30106. Rented or leased motor vehicle safety and responsibility","tname":"Transportation","by":{"1":"24","3":"21"}},{"t":"law","label":"Pub. L. No. 99-554","url":"https://www.govinfo.gov/link/statute/100/3117","by":{"1":"24"}},{"t":"case","label":"Archer v. Warner","cite":"538 U.S. 314","y":2003,"id":"2002/01-1418","sc":1,"sum":"The Court held that a debt for money promised in a settlement agreement accompanied by the release of underlying tort claims can amount to a debt for money obtained by fraud, within the nondischargeability statute's terms. \"We conclude that the Archers' settlement agreement and releases may have worked a kind of novation, but that fact does not bar the Archers from showing that the settlement debt arose out of 'false pretences, a false representation, or actual fraud,' and consequently is nondischargeable,\" wrote Justice Breyer.","sumSrc":"Oyez","by":{"2":"17","3":"17"}},{"t":"case","label":"Hersh v. United States ex rel. Mukasey","cite":"553 F.3d 743","y":2008,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/553/743/","by":{"2":"28"}},{"t":"case","label":"Johnson v. United States","cite":"559 U.S. 133","y":2010,"id":"2009/08-6925","sc":1,"sum":"The Court held that the Eleventh Circuit Court of Appeals was bound by Florida state law in considering a felony battery charge.","sumSrc":"Oyez","by":{"2":"26"}},{"t":"case","label":"Raleigh v. Illinois Dep’t of Revenue","cite":"530 U.S. 15","y":2000,"id":"1999/99-387","sc":1,"sum":"The Court held that \"[w]hen the substantive law creating a tax obligation puts the burden of proof on a taxpayer, the burden of proof on the tax claim in bankruptcy court remains where the substantive law put it (in this case, on the trustee in bankruptcy).\" The Court concluded that the bankruptcy estate's obligation to the Department was established by the state's tax code and that the Bankruptcy Code made no provision for altering the burden on a tax claim, and its silence said that no change was intended.","sumSrc":"Oyez","by":{"2":"11"}},{"t":"case","label":"Ransom v. FIA Card Servs., N.A.","cite":"562 U.S. 61","y":2011,"id":"2010/09-907","sc":1,"sum":"The Court held that a debtor who does not make a loan or lease payment could not take the car-ownership deduction.","sumSrc":"Oyez","by":{"2":"10"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"15, 26"}},{"t":"case","label":"Travelers Cas. & Sur. Co. of Am. v. Pacific Gas & Elec. Co.","cite":"549 U.S. 443","y":2007,"id":"2006/05-1429","sc":1,"sum":"Justice Samuel Alito issued the unanimous opinion, which found that the Bankruptcy Code did not expressly waive the contractual obligation to reimburse attorney fees even if incurred in federal litigation.","sumSrc":"Oyez","by":{"2":"11","3":"18"}},{"t":"case","label":"United States v. Sotelo","cite":"436 U.S. 268","y":1978,"id":"1977/76-1800","sc":1,"sum":"Respondents liability under § 6672 is nondischargeable in bankruptcy under § 17a (1) (e).","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"31"}},{"t":"usc","label":"11 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/11/301","by":{"2":"1"}},{"t":"usc","label":"11 U.S.C. § 307","url":"https://www.law.cornell.edu/uscode/text/11/307","by":{"2":"1"}},{"t":"usc","label":"11 U.S.C. § 501","url":"https://www.law.cornell.edu/uscode/text/11/501","by":{"2":"29"}},{"t":"usc","label":"11 U.S.C. § 521","url":"https://www.law.cornell.edu/uscode/text/11/521","subs":["(a)(1)"],"by":{"2":"29"}},{"t":"usc","label":"11 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/11/701","by":{"2":"3, 4, 6, 10, 24"}},{"t":"usc","label":"11 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/11/1101","by":{"2":"3, 24"}},{"t":"usc","label":"11 U.S.C. § 1201","url":"https://www.law.cornell.edu/uscode/text/11/1201","by":{"2":"3, 24"}},{"t":"usc","label":"11 U.S.C. § 1301","url":"https://www.law.cornell.edu/uscode/text/11/1301","by":{"2":"3, 24"}},{"t":"law","label":"National Bankruptcy Review Commission Act, Pub. L. No. 103-394","url":"https://www.govinfo.gov/link/statute/108/4147","by":{"2":"22"}},{"t":"law","label":"Pub. L. No. 116-54","url":"https://www.govinfo.gov/link/plaw/116/public/54","by":{"2":"2"}},{"t":"usc","label":"28 U.S.C. § 581-589a","url":"https://www.law.cornell.edu/uscode/text/28/581-589a","by":{"2":"1"}},{"t":"case","label":"Bruesewitz v. Wyeth LLC","cite":"562 U.S. 223","y":2011,"id":"2010/09-152","sc":1,"sum":"The Court held that the National Childhood Vaccine Injury Act shielded manufacturers from certain product liability lawsuits that seek damages for serious health problems suffered by children.","sumSrc":"Oyez","by":{"3":"24"}},{"t":"case","label":"Cummings v. HPG Int’l","cite":"244 F.3d 16","y":2001,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/244/16/","by":{"3":"14"}},{"t":"case","label":"Dinsmore-Poff v. Alvord","cite":"972 P.2d 978","y":1999,"court":"Alaska","url":"https://www.courtlistener.com/c/P.2d/972/978/","by":{"3":"19"}},{"t":"case","label":"Egbert v. Boule","cite":"142 S. Ct. 1793","y":2022,"id":"2021/21-147","sc":1,"sum":"The authority of a court to imply a cause of action under Bivens v. Six Unknown Fed. Narcotics Agents, 403 U. S. 388, does not extend to either Boule’s Fourth Amendment excessive-force claim or his First Amendment retaliation claim.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"15"}},{"t":"case","label":"Gebser v. Lago Vista Indep. Sch. Dist.","cite":"524 U.S. 274","y":1998,"id":"1997/96-1866","sc":1,"ar":3,"sum":"In a 5-to-4 decision the Court held that two minimal criteria must be met in order for an aggrieved party to recover sexual harassment damages under the Amendments. First, the party must show that a school district official, with the ability to institute corrective measures, knew of the forbidden conduct.","sumSrc":"Oyez","by":{"3":"20"}},{"t":"case","label":"Jesner v. Arab Bank, PLC","cite":"138 S. Ct. 1386","y":2018,"id":"2017/16-499","sc":1,"sum":"The Court held that the Alien Tort Statute does not permit lawsuits against corporations.","sumSrc":"Oyez","by":{"3":"20"}},{"t":"case","label":"Mary Pickford Co. v. Bayly Bros.","cite":"86 P.2d 102","y":1939,"court":"Cal.","url":"https://www.courtlistener.com/c/P.2d/86/102/","by":{"3":"14"}},{"t":"case","label":"Monell v. Dep’t of Soc. Serv.","cite":"436 U.S. 658","y":1978,"id":"1977/75-1914","sc":1,"sum":"The Court held that the legislative history of the Civil Rights Act of 1871, and specifically the Sherman Amendment, indicated that municipalities could be liable for the infringement of constitutional rights. Additionally, by 1871 there was a clear legislative and precedent-based history for municipal corporations — such as a school board — to be considered a “person” for the purpose of lawsuits and liability.","sumSrc":"Oyez","by":{"3":"21"}},{"t":"case","label":"Peter v. Nantkwest, Inc.","cite":"140 S. Ct. 365","y":2019,"id":"2019/18-801","sc":1,"sum":"The Court held that the phrase “[a]ll the expenses of the proceedings” in 35 U.S.C. § 145 does not include attorneys’ fees incurred as a result of defending the agency in § 145 litigation.","sumSrc":"Oyez","by":{"3":"17"}},{"t":"case","label":"Siegel v. Fitzgerald","cite":"142 S. Ct. 1770","y":2022,"id":"2021/21-441","sc":1,"sum":"Congress’ enactment of a significant fee increase that exempted debtors in two States violated the uniformity requirement of the Bankruptcy Clause.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"19"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","by":{"3":"21"}},{"t":"reg","label":"26 C.F.R. § 1.6061-1","url":"https://www.ecfr.gov/current/title-26/section-1.6061-1","by":{"3":"9"}}]};